import React from 'react';
import Header from '../Header';
import './Itempage.css';
import Footer from '../Footer';
import saree1 from './saree1.jpg';

function Itempage() {
    return (
            <div class="item-page">
                <div class="item-image">
                    <img src="item-image.jpg" alt="Item Name"/>
                </div>
                <div class="item-details">
                    <h1>Item Name</h1>
                    <p class="item-description">This is a great description of the item that highlights its features, material, and care instructions.</p>
                    <span class="item-price">$49.99</span>
                    <div class="item-size">
                        <label for="size">Size:</label>
                        <select id="size">
                            <option value="s">S</option>
                            <option value="m">M</option>
                            <option value="l">L</option>
                            <option value="xl">XL</option>
                        </select>
                    </div>
                    <button class="add-to-cart">Add to Cart</button>
                </div>
            </div>
    );
}

export default Itempage;
